  let angleA = 0.0;
  let angleB = angleA + angleOffset;

  let k = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 2.0, 4.0);

  for (let i = 0; i < height; i += (Math.max(0.001, Math.abs(curveWidth*k)) || 1)) {
    let waveColor = map(i, 0, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))+10, 0, 255);
    noStroke();

    push();
    translate(0, 400);
    fill(waveColor);
    beginShape(QUAD_STRIP);
    for (let x = 0; x <= width; x += 10) {
      //let y1 = i + (sin(angleA)* curveWidth);
